	describe('behaviour on topic purge', () => {
		let topicObj;
		const purgeThumbPaths = [
			path.join(nconf.get('upload_path'), 'files', 'exclusive-purge-thumb.png'),
			path.join(nconf.get('upload_path'), 'files', 'exclusive-purge-thumb2.png'),
			path.join(nconf.get('upload_path'), 'exclusive-purge-other-thumb.png'),
		];

		before(async () => {
			topicObj = await topics.post({
				uid: adminUid,
				cid: categoryObj.cid,
				title: 'Test Topic Title',
				content: 'The content of test topic',
			});

			purgeThumbPaths.forEach(absolutePath => fs.writeFileSync(absolutePath, ''));
			await Promise.all(purgeThumbPaths.map(async absolutePath => topics.thumbs.associate({
				id: topicObj.topicData.tid,
				path: absolutePath,
			})));

			await topics.purgePostsAndTopic(topicObj.topicData.tid, adminUid);
		});

		it('should no longer have a :thumbs zset', async () => {
			assert.strictEqual(await db.exists(`topic:${topicObj.topicData.tid}:thumbs`), false);
		});

		it('should not leave files behind', async () => {
			const exists = await Promise.all(purgeThumbPaths.map(async absolutePath => file.exists(absolutePath)));
			assert.strictEqual(exists.some(Boolean), false);
		});

		it('should keep a thumbnail still referenced by another post', async () => {
			const filename = 'shared-purge-thumb.png';
			const absolutePath = path.join(nconf.get('upload_path'), 'files', filename);
			fs.writeFileSync(absolutePath, '');
			try {
				const withThumb = await topics.post({
					uid: adminUid,
					cid: categoryObj.cid,
					title: 'Topic with shared thumbnail',
					content: 'The content of test topic',
				});
				await topics.thumbs.associate({ id: withThumb.topicData.tid, path: absolutePath });
				const otherTopic = await topics.post({
					uid: adminUid,
					cid: categoryObj.cid,
					title: 'Topic referencing a shared thumbnail',
					content: `[image](/assets/uploads/files/${filename})`,
				});

				await topics.purgePostsAndTopic(withThumb.topicData.tid, adminUid);
				assert.strictEqual(await file.exists(absolutePath), true);

				await topics.purgePostsAndTopic(otherTopic.topicData.tid, adminUid);
				assert.strictEqual(await file.exists(absolutePath), false);
			} finally {
				if (fs.existsSync(absolutePath)) {
					fs.unlinkSync(absolutePath);
				}
			}
		});

		it('should retain thumbnails when orphaned uploads are preserved', async () => {
			const filename = 'preserved-purge-thumb.png';
			const absolutePath = path.join(nconf.get('upload_path'), 'files', filename);
			const otherPath = path.join(nconf.get('upload_path'), 'preserved-other-thumb.png');
			const previous = meta.config.preserveOrphanedUploads;
			fs.writeFileSync(absolutePath, '');
			fs.writeFileSync(otherPath, '');
			meta.config.preserveOrphanedUploads = 1;
			try {
				const withThumb = await topics.post({
					uid: adminUid,
					cid: categoryObj.cid,
					title: 'Topic with preserved thumbnail',
					content: 'The content of test topic',
				});
				await topics.thumbs.associate({ id: withThumb.topicData.tid, path: absolutePath });
				await topics.thumbs.associate({ id: withThumb.topicData.tid, path: otherPath });
				await topics.purgePostsAndTopic(withThumb.topicData.tid, adminUid);
				assert.strictEqual(await file.exists(absolutePath), true);
				assert.strictEqual(await file.exists(otherPath), true);
			} finally {
				meta.config.preserveOrphanedUploads = previous;
				if (fs.existsSync(absolutePath)) {
					fs.unlinkSync(absolutePath);
				}
				if (fs.existsSync(otherPath)) {
					fs.unlinkSync(otherPath);
				}
			}
		});
	});
